        "rule": "UAE PDPL Article 7 requires the controller to take appropriate technical and organizational measures to protect personal data and ensure it is not breached.",
        "inference": "Preserving logs and evidence is a necessary technical measure to support breach investigation and regulatory reporting."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0021",
          "quote": "Take appropriate technical and organizational measures to implement the necessary standards to protect and secure Personal Data in order to preserve its confidentiality and privacy, and to ensure that it is not breached, destroyed, altered or tampered with, taking into account the nature, scope and purposes of processing and the possibility of risks to the confidentiality and privacy of the Data Subject's Personal Data."
        }
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "DPA",
        "content": "Personal data breach notification: a vendor update changed the chatbot retrieval scope from 'own account' to 'all accounts'; about 1,200 sessions over three days exposed other subscribers' billing address and call records; vendor hosts model and chat logs outside the UAE."
      },
      "inject_refs": ["S2-I2"],
      "rationale": {
        "observation": "S2-I2 reports a personal data breach affecting other subscribers' data in about 1,200 chatbot sessions over three days.",
        "rule": "UAE PDPL Article 7 requires appropriate technical and organizational measures to protect personal data and ensure it is not breached.",
        "inference": "Notifying the Data Protection Authority is part of an appropriate organizational response to a personal data breach."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0021",
          "quote": "Take appropriate technical and organizational measures to implement the necessary standards to protect and secure Personal Data in order to preserve its confidentiality and privacy, and to ensure that it is not breached, destroyed, altered or tampered with, taking into account the nature, scope and purposes of processing and the possibility of risks to the confidentiality and privacy of the Data Subject's Personal Data."
        }
      ]
    },
    {
      "type": "gap",
